SELECT sku, gtin, name, pack, case_units
FROM store.products
WHERE lower(name) LIKE '%atta%' AND lower(pack) LIKE '%5%kg%';

SELECT sku, gtin, name, pack, case_units
FROM store.products
WHERE lower(name) LIKE '%atta%' AND pack = '5 kg';

SELECT *
FROM store.daily_sales
WHERE sku = 'ATTA-WW-5KG' AND date >= DATE '2026-06-01' AND date <= DATE '2026-06-30';
